<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Csrf;use App\Core\Database;use App\Services\TestAutomaticJudgeService;$pdo=Database::connection();$token=(string)($_GET['token']??$_POST['token']??'');$session=TestAutomaticJudgeService::byToken($pdo,$token);if(!$session){http_response_code(404);exit('Invalid or expired test judge link.');}$sessionId=(int)$session['id'];$roundId=(int)$session['round_id'];$judgeId=(int)$session['judge_id'];$error='';$notice='';TestAutomaticJudgeService::markOpened($pdo,$sessionId);$rs=$pdo->prepare('SELECT yes_count,yes_weight,alt1_weight,alt2_weight,alt3_weight,round_type FROM bdc_test_scoring_rounds WHERE id=:r');$rs->execute(['r'=>$roundId]);$round=$rs->fetch()?:['yes_count'=>10,'yes_weight'=>10,'alt1_weight'=>4.5,'alt2_weight'=>4.3,'alt3_weight'=>4.2,'round_type'=>'heats'];$scope=(string)$session['scoring_scope'];$entrySql="SELECT * FROM bdc_test_scoring_entries WHERE round_id=:r AND entry_status='active'";$params=['r'=>$roundId];if($scope!=='all'){$entrySql.=' AND dance_role=:role';$params['role']=$scope;}$entrySql.=' ORDER BY dance_role,bib_number';$q=$pdo->prepare($entrySql);$q->execute($params);$entries=$q->fetchAll();$byRole=['leader'=>[],'follower'=>[]];foreach($entries as $e)$byRole[$e['dance_role']][]=$e;
function validateTestMarks(array $entries,array $marks,int $yesLimit):void{$roles=['leader'=>[],'follower'=>[]];foreach($entries as $e)$roles[$e['dance_role']][]=$e;foreach($roles as $role=>$rows){if(!$rows)continue;$yes=0;$alts=[1=>0,2=>0,3=>0];foreach($rows as $e){$v=(string)($marks[(int)$e['id']]??'blank');if($v==='yes')$yes++;elseif(in_array($v,['alt1','alt2','alt3'],true))$alts[(int)substr($v,-1)]++;}if($yes>$yesLimit)throw new RuntimeException('Maximum '.$yesLimit.' YES selections allowed for '.ucfirst($role).'s.');foreach($alts as $n=>$count)if($count>1)throw new RuntimeException('A'.$n.' can only be assigned once for '.ucfirst($role).'s.');}}
try{if($_SERVER['REQUEST_METHOD']==='POST'){if((string)$session['status']==='submitted')throw new RuntimeException('Scores are already submitted and locked.');if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'save');$marks=$_POST['mark']??[];if($action==='generate_random'){$marks=[];foreach($byRole as $role=>$rows){if(!$rows)continue;$ids=array_map(fn($e)=>(int)$e['id'],$rows);shuffle($ids);$yes=min((int)$round['yes_count'],count($ids));foreach($ids as $id)$marks[$id]='blank';for($i=0;$i<$yes;$i++)$marks[$ids[$i]]='yes';$cursor=$yes;foreach([1,2,3] as $alt)if(isset($ids[$cursor]))$marks[$ids[$cursor++]]='alt'.$alt;}}validateTestMarks($entries,$marks,(int)$round['yes_count']);$up=$pdo->prepare("INSERT INTO bdc_test_scoring_marks(round_id,entry_id,judge_id,mark_type,alt_rank,weighted_score,updated_by) VALUES(:r,:e,:j,:t,:a,:w,NULL) ON DUPLICATE KEY UPDATE mark_type=VALUES(mark_type),alt_rank=VALUES(alt_rank),weighted_score=VALUES(weighted_score),updated_at=NOW()");foreach($entries as $entry){$eid=(int)$entry['id'];$value=(string)($marks[$eid]??'blank');$type='blank';$alt=null;$weight=0.0;if($value==='yes'){$type='yes';$weight=(float)$round['yes_weight'];}elseif(in_array($value,['alt1','alt2','alt3'],true)){$type='alt';$alt=(int)substr($value,-1);$weight=(float)$round['alt'.$alt.'_weight'];}$up->execute(['r'=>$roundId,'e'=>$eid,'j'=>$judgeId,'t'=>$type,'a'=>$alt,'w'=>$weight]);}TestAutomaticJudgeService::markSaved($pdo,$sessionId);if($action==='submit'){foreach($byRole as $role=>$rows){if(!$rows)continue;$yes=0;$alts=[1=>0,2=>0,3=>0];foreach($rows as $e){$v=(string)($marks[(int)$e['id']]??'blank');if($v==='yes')$yes++;elseif(str_starts_with($v,'alt'))$alts[(int)substr($v,-1)]++;}if($yes!==(int)$round['yes_count'])throw new RuntimeException('Select exactly '.$round['yes_count'].' YES for '.ucfirst($role).'s before submitting.');foreach($alts as $n=>$count)if($count>1)throw new RuntimeException('A'.$n.' can only be used once for '.ucfirst($role).'s.');}TestAutomaticJudgeService::submit($pdo,$sessionId);$notice='Scores submitted and locked.';}elseif($action==='generate_random')$notice='Valid random test scores generated. Review or submit when ready.';else$notice='Scores saved.';$session=TestAutomaticJudgeService::byToken($pdo,$token);}}catch(Throwable $e){$error=$e->getMessage();}
$existing=[];$m=$pdo->prepare('SELECT entry_id,mark_type,alt_rank FROM bdc_test_scoring_marks WHERE round_id=:r AND judge_id=:j');$m->execute(['r'=>$roundId,'j'=>$judgeId]);foreach($m->fetchAll() as $row){$v=(string)$row['mark_type'];if($v==='alt')$v='alt'.(int)$row['alt_rank'];$existing[(int)$row['entry_id']]=$v;}$locked=(string)$session['status']==='submitted';$counts=['leader'=>['yes'=>0,1=>0,2=>0,3=>0],'follower'=>['yes'=>0,1=>0,2=>0,3=>0]];foreach($entries as $e){$v=$existing[(int)$e['id']]??'blank';$role=$e['dance_role'];if($v==='yes')$counts[$role]['yes']++;elseif(str_starts_with($v,'alt'))$counts[$role][(int)substr($v,-1)]++;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Judge Scoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.score-row{background:#fff;border:1px solid #dee2e6;border-radius:12px;padding:14px;margin-bottom:10px}.mark-btn input{display:none}.mark-btn label{min-width:58px}.mark-btn input:checked+label{background:#212529;color:#fff}.counter{position:sticky;top:0;z-index:4;background:#fff;border:1px solid #dee2e6;border-radius:10px;padding:10px;margin-bottom:12px}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><span class="navbar-brand">BDC Automatic Scoring TEST</span><span class="badge text-bg-warning">TEST ONLY</span></div></nav><main class="container py-4" style="max-width:900px"><h1 class="h3"><?=e($session['event_name'])?></h1><div class="text-muted mb-3"><?=e($session['division'])?> · <?=e($session['judge_name'])?><?=((int)$session['is_chief']===1?' · Chief Judge':'')?></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if(!$locked):?><form method="post" class="mb-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-warning" name="action" value="generate_random">Generate Valid Random Scores</button></form><?php endif;?><?php foreach(['leader'=>'Leaders','follower'=>'Followers'] as $role=>$label):if(!$byRole[$role])continue;?><div class="counter"><strong><?=$label?></strong> · YES <?=$counts[$role]['yes']?>/<?=(int)$round['yes_count']?> · A1 <?=$counts[$role][1]?>/1 · A2 <?=$counts[$role][2]?>/1 · A3 <?=$counts[$role][3]?>/1</div><?php endforeach;?><?php if($locked):?><div class="alert alert-success"><strong>Submitted.</strong> These scores are locked.</div><?php endif;?><form method="post" id="scoreForm"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><?php foreach($entries as $e):$eid=(int)$e['id'];$selected=$existing[$eid]??'blank';?><div class="score-row" data-role="<?=e($e['dance_role'])?>"><strong>#<?=(int)$e['bib_number']?> <?=e($e['display_name'])?></strong><div class="small text-muted mb-2"><?=e(ucfirst($e['dance_role']))?></div><div class="d-flex gap-2 flex-wrap mark-btn"><?php foreach(['yes'=>'YES','alt1'=>'A1','alt2'=>'A2','alt3'=>'A3','blank'=>'Blank'] as $value=>$label):?><span><input id="m<?=$eid?>-<?=$value?>" type="radio" name="mark[<?=$eid?>]" value="<?=$value?>" <?=($selected===$value?'checked':'')?> <?=($locked?'disabled':'')?>><label class="btn btn-outline-dark" for="m<?=$eid?>-<?=$value?>"><?=$label?></label></span><?php endforeach;?></div></div><?php endforeach;?><?php if(!$locked):?><div class="position-sticky bottom-0 bg-light py-3 d-flex gap-2"><button class="btn btn-outline-primary flex-fill" name="action" value="save">Save Draft</button><button class="btn btn-success flex-fill" name="action" value="submit" onclick="return confirm('Submit and lock your scores?')">Submit & Lock</button></div><?php endif;?></form></main><?php if(!$locked):?><script>const limit=<?=(int)$round['yes_count']?>;document.querySelectorAll('.mark-btn input').forEach(i=>i.addEventListener('change',e=>{const role=i.closest('.score-row').dataset.role,val=i.value;if(val==='blank')return;const checked=[...document.querySelectorAll('.score-row[data-role="'+role+'"] input:checked')];if(val==='yes'&&checked.filter(x=>x.value==='yes').length>limit){alert('Maximum '+limit+' YES selections allowed for '+role+'s.');document.querySelector('#m'+i.id.split('-')[0].substring(1)+'-blank').checked=true;}if(val.startsWith('alt')&&checked.filter(x=>x.value===val).length>1){alert(val.toUpperCase()+' can only be assigned once for '+role+'s.');document.querySelector('#m'+i.id.split('-')[0].substring(1)+'-blank').checked=true;}}));</script><?php endif;?></body></html>